/*
 * Custom Plugin Demo
 * 
 * This example demonstrates how to use a custom third-party plugin.
 * 
 * To enable this plugin:
 * 1. Copy js/libraries/yourlibrary.js to your project
 * 2. Add <script src="js/libraries/yourlibrary.js"></script> to index.html
 * 3. Refresh the page
 * 
 * Circuit:
 * - Potentiometer on A0 (simulates sensor input)
 * - LED on D9 (simulates actuator output)
 * 
 * The plugin provides a YourClass with begin(), readValue(), writeValue()
 */

#include <YourLibrary.h>

YourClass myDevice;

int sensorPin = A0;
int ledPin = 9;

void setup() {
  Serial.begin(115200);
  while (!Serial);

  // Initialize custom plugin device
  myDevice.begin();

  pinMode(ledPin, OUTPUT);

  Serial.println(F("=== Custom Plugin Demo ==="));
  Serial.println(F("Plugin constants:"));
  Serial.print(F("  YOUR_MODE_A = ")); Serial.println(YOUR_MODE_A);
  Serial.print(F("  YOUR_MODE_B = ")); Serial.println(YOUR_MODE_B);
  Serial.print(F("  YOUR_CONSTANT = ")); Serial.println(YOUR_CONSTANT);
}

void loop() {
  // Read from potentiometer (0-1023)
  int sensorValue = analogRead(sensorPin);

  // Use custom plugin to process the value
  int processed = myDevice.readValue();

  // Write to custom plugin (controls LED brightness via plugin)
  myDevice.writeValue(sensorValue / 4); // Scale to 0-255

  // Also control LED directly for visual feedback
  analogWrite(ledPin, sensorValue / 4);

  // Log to serial monitor
  Serial.print(F("Sensor: "));
  Serial.print(sensorValue);
  Serial.print(F("  Plugin Read: "));
  Serial.print(processed);
  Serial.print(F("  LED: "));
  Serial.println(sensorValue / 4);

  delay(200);
}
